def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    # iterative find to avoid recursion limit
    def find_iter(x):
        if parent[x] != x:
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
        return x

    def union(a, b):
        ra = find_iter(a)
        rb = find_iter(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for _ in range(m):
        u = int(next(it)); v = int(next(it))
        union(u, v)

    components = 0
    for i in range(1, n + 1):
        if find_iter(i) == i:
            components += 1

    print(m - n + components)

