class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1

        appearance = collections.Counter()
        for i in range(n - k + 1):
            window = collections.Counter(nums[i:i + k])
            for value in window:
                appearance[value] += 1

        answer = -1
        for value, count in appearance.items():
            if count == 1:
                answer = max(answer, value)
        return answer

