class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        groups = {}
        for i, x in enumerate(nums):
            groups.setdefault(x, []).append(i)

        ans = [-1] * n

        for idxs in groups.values():
            k = len(idxs)
            if k == 1:
                continue

            gaps = [0] * k
            for i in range(k):
                gaps[i] = (idxs[(i + 1) % k] - idxs[i]) % n

            for i in range(k):
                g_next = gaps[i]
                g_prev = gaps[i - 1] if i > 0 else gaps[k - 1]
                d_next = min(g_next, n - g_next)
                d_prev = min(g_prev, n - g_prev)
                ans[idxs[i]] = min(d_next, d_prev)

        return [ans[q] for q in queries]

