class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        codes = [ord(ch) - ord('a') for ch in s]

        dist = [[0] * n for _ in range(n)]
        for i in range(n):
            ci = codes[i]
            di = dist[i]
            for j in range(n):
                d = ci - codes[j]
                if d < 0:
                    d = -d
                if d > 13:
                    d = 26 - d
                di[j] = d

        # dp[i][j][b] = best palindrome length obtainable from s[i..j]
        # using at most b operations on that interval.
        dp = [[[0] * (k + 1) for _ in range(n + 1)] for _ in range(n + 1)]
        for i in range(n):
            for b in range(k + 1):
                dp[i][i][b] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for b in range(k + 1):
                    best = dp[i + 1][j][b]
                    rj = dp[i][j - 1][b]
                    if rj > best:
                        best = rj

                    c = dist[i][j]
                    if c <= b:
                        val = 0
                        if i + 1 <= j - 1:
                            val = dp[i + 1][j - 1][b - c]
                        val += 2
                        if val > best:
                            best = val

                    dp[i][j][b] = best

        return dp[0][n - 1][k]

