class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        NEG = float('-inf')
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        # dp_prev[i] = max sum using exactly (j-1) intervals inside nums[:i]
        dp_prev = [0] * (n + 1)

        for _ in range(k):
            dp_curr = [NEG] * (n + 1)
            running = NEG          # max of dp_prev[s] - prefix[s] for s <= i - m
            ptr = 0                # next s to incorporate
            for i in range(n + 1):
                s_max = i - m
                while ptr <= s_max:
                    v = dp_prev[ptr] - prefix[ptr]
                    if v > running:
                        running = v
                    ptr += 1
                term2 = NEG
                if running != NEG:
                    term2 = prefix[i] + running
                if i == 0:
                    dp_curr[0] = NEG
                else:
                    dp_curr[i] = dp_curr[i - 1]
                    if term2 > dp_curr[i]:
                        dp_curr[i] = term2
            dp_prev = dp_curr

        return int(dp_prev[n])

