def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    M = data[1]
    P = data[2:2 + n]

    def k_count(t, p):
        # number of units of product p whose marginal cost (2j-1)*p <= t
        return (t + p) // (2 * p)

    def count_cost_at(t):
        ksum = 0
        csum = 0
        for p in P:
            k = k_count(t, p)
            ksum += k
            csum += p * k * k
        return ksum, csum

    def count_at(t):
        total = 0
        for p in P:
            total += k_count(t, p)
        return total

    def feasible(s):
        if s <= 0:
            return True
        # minimal integer t such that K(t) >= s
        lo, hi = 0, 3_000_000_000  # safe upper bound
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if count_at(mid) >= s:
                hi = mid
            else:
                lo = mid
        t = hi
        # compute K(t), S(t), K(t-1), cost of units with cost < t
        kt = klt = 0
        st = 0
        cost_lt = 0
        for p in P:
            k = k_count(t, p)
            klt_i = k_count(t - 1, p) if t > 0 else 0
            kt += k
            st += p * k * k
            klt += klt_i
            cost_lt += p * klt_i * klt_i
        if kt == s:
            return st <= M
        # s > klt; we add s-klt units of cost t
        cost = cost_lt + (s - klt) * t
        return cost <= M

    low, high = 0, math.isqrt(M * n) + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

