class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        if n == 0:
            return -1

        max_v = max(nums)
        # mul_bits[v][q] is the bitmask for product q*v, or 0 if it exceeds limit.
        mul_bits = [None] * (max_v + 1)
        for v in range(2, max_v + 1):
            lst = [0] * (limit + 1)
            for q in range(limit // v + 1):
                lst[q] = 1 << (q * v)
            mul_bits[v] = lst

        # State: (alternating_sum, parity_of_next_selected_index)
        # Value: bitmask of achievable nonempty subsequence products (bit p = product p).
        current = {(0, 0): 0}

        for x in nums:
            nxt = {}
            if x == 0:
                for (s, parity), bits in current.items():
                    # skip this zero
                    key = (s, parity)
                    nxt[key] = nxt.get(key, 0) | bits
                    # include this zero: product becomes 0, s unchanged, parity flips
                    key2 = (s, 1 - parity)
                    nxt[key2] = nxt.get(key2, 0) | 1
                current = nxt
                continue

            for (s, parity), bits in current.items():
                # skip x
                key = (s, parity)
                nxt[key] = nxt.get(key, 0) | bits

                # include x
                if parity == 0:
                    s2 = s + x
                    parity2 = 1
                else:
                    s2 = s - x
                    parity2 = 0

                if x == 1:
                    scaled = bits
                    if not bits:
                        scaled = 1  # subsequence consisting only of this 1
                else:
                    scaled = 0
                    if not bits:
                        scaled = 1 << x  # subsequence consisting only of this element
                    else:
                        b = bits
                        while b:
                            lb = b & -b
                            q = lb.bit_length() - 1
                            b ^= lb
                            scaled |= mul_bits[x][q]
                key2 = (s2, parity2)
                nxt[key2] = nxt.get(key2, 0) | scaled

            current = nxt

        bits = current.get((k, 0), 0) | current.get((k, 1), 0)
        if bits == 0:
            return -1
        return bits.bit_length() - 1

