class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)

        # prefix values modulo each possible last digit d (1..9)
        p = [[0] * (n + 1) for _ in range(10)]
        for d in range(1, 10):
            mod = d
            acc = 0
            arr = p[d]
            for k in range(1, n + 1):
                acc = (acc * 10 + (ord(s[k - 1]) - 48)) % mod
                arr[k] = acc

        # For each d, determine:
        #   K: initial number of lengths L for which a_L is special (not periodic)
        #   t: period for L > K (usually 1)
        #   a_for_q[q]: a_L for L > K with L % t == q (using q = L % t)
        K = {d: 0 for d in range(1, 10)}
        t = {d: 1 for d in range(1, 10)}
        a_for_q = {}

        for d in range(1, 10):
            if d == 4:
                K[d] = 1
                t[d] = 1
                a_for_q[d] = [0]  # a_L = 0 for L >= 2
            elif d == 8:
                K[d] = 2
                t[d] = 1
                a_for_q[d] = [0]  # a_L = 0 for L >= 3
            elif d == 7:
                K[d] = 0
                t[d] = 6
                powers = [pow(10, L, d) for L in range(1, 7)]  # L=1..6
                arr = [0] * 6
                for L in range(1, 7):
                    arr[L % 6] = powers[L - 1]
                a_for_q[d] = arr
            else:
                K[d] = 0
                t[d] = 1
                a_for_q[d] = [pow(10, 1, d)]

        # cnt[d][r][res] = number of indices i in current range [0, k] such that
        # p[d][i] == r and i % t[d] == res.
        cnt = [
            [[0 for _ in range(t[d])] for _ in range(d)]
            for d in range(1, 10)
        ]

        def add_i(i: int):
            for d in range(1, 10):
                r = p[d][i]
                res = i % t[d]
                cnt[d][r][res] += 1

        # For m = 1, i ranges over [0, 0].
        add_i(0)

        total = 0

        for m in range(1, n + 1):
            d = ord(s[m - 1]) - 48

            if d != 0:
                pm = p[d][m]

                # lengths L <= K are checked directly
                for L in range(1, K[d] + 1):
                    i = m - L
                    if i >= 0:
                        # a_L direct
                        if d == 4:
                            a_L = 2
                        elif d == 8:
                            a_L = 2 if L == 1 else 4
                        else:
                            a_L = pow(10, L, d)
                        if (p[d][i] * a_L) % d == pm:
                            total += 1

                # lengths L > K use the periodic bucket
                td = t[d]
                base = 0  # not needed
                for q in range(td):
                    a_val = a_for_q[d][q]
                    # i % t == (m - L) % t == (m - q) % t
                    res = (m - q) % td
                    for r in range(d):
                        count = cnt[d][r][res]
                        if count == 0:
                            continue

                        # subtract indices i with L <= K that fall into this bucket
                        for L in range(1, K[d] + 1):
                            i = m - L
                            if i >= 0 and p[d][i] == r and (i % td) == res:
                                count -= 1

                        if count <= 0:
                            continue

                        # Solve p[m] == r * a_val (mod d)
                        # Iterate possible r only; r is already fixed. Check directly.
                        if (r * a_val) % d == pm:
                            total += count

            # Prepare counts for the next m: range becomes [0, m]
            add_i(m)

        return total

